/** @jsx jsx */
import { graphql, HeadFC, Link, useStaticQuery } from "gatsby"
import { Box, jsx } from "theme-ui"
import Layout from "@lekoarts/gatsby-theme-minimal-blog/src/components/layout"
import Title from "@lekoarts/gatsby-theme-minimal-blog/src/components/title"
import Listing from "@lekoarts/gatsby-theme-minimal-blog/src/components/listing"
import List from "@lekoarts/gatsby-theme-minimal-blog/src/components/list"
import useMinimalBlogConfig from "@lekoarts/gatsby-theme-minimal-blog/src/hooks/use-minimal-blog-config"
import useSiteMetadata from "@lekoarts/gatsby-theme-minimal-blog/src/hooks/use-site-metadata"
import replaceSlashes from "@lekoarts/gatsby-theme-minimal-blog/src/utils/replaceSlashes"
import { visuallyHidden } from "@lekoarts/gatsby-theme-minimal-blog/src/styles/utils"
import Seo from "@lekoarts/gatsby-theme-minimal-blog/src/components/seo"
import Hero from "../../gatsby-theme-minimal-blog/texts/hero.mdx"
import Bottom from "../../gatsby-theme-minimal-blog/texts/bottom.mdx"

const HomepageWithFivePosts = () => {
  const { basePath, blogPath } = useMinimalBlogConfig()
  const { siteTitle } = useSiteMetadata()
  const { allPost } = useStaticQuery(graphql`
    query HomepageWithFivePosts {
      allPost(sort: { date: DESC }, limit: 5) {
        nodes {
          slug
          title
          date(formatString: "DD MMM YYYY")
          excerpt
          timeToRead
          description
          tags {
            name
            slug
          }
        }
      }
    }
  `)

  return (
    <Layout>
      <h1 sx={visuallyHidden}>{siteTitle}</h1>
      <section
        sx={{
          mb: [4, 5, 6],
          p: { fontSize: [1, 2, 3], mt: 2 },
          variant: `section_hero`,
        }}
      >
        <Hero />
      </section>
      <Title text="Latest Posts">
        <Link to={replaceSlashes(`/${basePath}/${blogPath}`)}>
          Read all posts
        </Link>
      </Title>
      <Box sx={{ "> section": { mb: [4, 5, 6] } }}>
        <Listing posts={allPost.nodes} showTags={false} />
      </Box>
      <List>
        <Bottom />
      </List>
    </Layout>
  )
}

export default HomepageWithFivePosts

export const Head: HeadFC = () => <Seo />
